// ❌ BAD: Executes 1 query for products + 100 queries for categories
$products = Product::where('active', true)->get();
foreach ($products as $product) {
    echo $product->category->name;
}

tech_tips.solution_code:
// ✅ PRO: Executes exactly 2 optimized queries regardless of volume
$products = Product::with('category')
    ->where('active', true)
    ->get();

