# ❌ BAD: Synchronous CRM calls delay webhook response and cause timeouts
@app.post('/webhook')
def handle_lead(lead: LeadSchema):
    enrich_lead_data(lead)  # takes 3.5 seconds!
    return {'status': 'processed'}

tech_tips.solution_code:
# ✅ PRO: Return 200 OK instantly and process asynchronously
@app.post('/webhook')
async def handle_lead(lead: LeadSchema, bg_tasks: BackgroundTasks):
    bg_tasks.add_task(enrich_lead_data, lead)
    return {'status': 'received', 'latency_ms': 12}
